<?php
$filters=$filters??['ano'=>'','periodo'=>'','turno'=>'','q'=>''];$periodOptions=$periodOptions??[];$yearOptions=$yearOptions??[];$hasContributions=$hasContributions??(bool)$rows;
$exportUrl='/consolidados?'.http_build_query(array_filter($filters,static fn($value):bool=>$value!=='')+['formato'=>'csv']);
ob_start();?>
<section class="page-heading"><div><p class="eyebrow">Documento da escola</p><h1>Conselho coletivo</h1><p>Uma seção compartilhada para cada turma, reunindo as contribuições de todos os professores.</p></div><div class="actions"><a class="button" href="<?=e($exportUrl)?>">Exportar planilha (CSV)</a><button class="primary" type="button" data-print-page>Imprimir</button></div></section>
<section class="card query-filter-card" aria-label="Filtros dos relatos">
    <form method="get" action="/consolidados" class="query-filters">
        <div class="grid">
            <label>Ano letivo<select name="ano"><option value="">Todos os anos</option><?php foreach($yearOptions as$year):?><option value="<?=e($year)?>" <?=(string)$year===$filters['ano']?'selected':''?>><?=e($year)?></option><?php endforeach;?><?php if($filters['ano']!==''&&!in_array((int)$filters['ano'],array_map('intval',$yearOptions),true)):?><option value="<?=e($filters['ano'])?>" selected><?=e($filters['ano'])?> (sem períodos)</option><?php endif;?></select></label>
            <label>Período<select name="periodo"><option value="">Todos os períodos</option><?php foreach($periodOptions as$option):?><option value="<?=e($option['id'])?>" <?=(string)$option['id']===$filters['periodo']?'selected':''?>><?=e($option['nome'].' · '.$option['ano_letivo'].' · '.($option['turno']==='VESPERTINO'?'Vespertino':($option['turno']==='MATUTINO'?'Matutino':'Todos os turnos')))?></option><?php endforeach;?><?php if($filters['periodo']!==''&&!in_array((int)$filters['periodo'],array_map('intval',array_column($periodOptions,'id')),true)):?><option value="<?=e($filters['periodo'])?>" selected>Período #<?=e($filters['periodo'])?> (indisponível)</option><?php endif;?></select></label>
            <label>Turno<select name="turno"><option value="">Todos os turnos</option><option value="MATUTINO" <?=$filters['turno']==='MATUTINO'?'selected':''?>>Matutino</option><option value="VESPERTINO" <?=$filters['turno']==='VESPERTINO'?'selected':''?>>Vespertino</option></select></label>
            <label>Buscar nos relatos<input type="search" name="q" maxlength="250" value="<?=e($filters['q'])?>" placeholder="Período, turma, relato ou autor"></label>
        </div><p class="helper">A busca considera o texto literal, incluindo acentos, sem diferenciar maiúsculas de minúsculas.</p><div class="actions"><button class="primary" type="submit">Aplicar filtros</button><a class="button" href="/consolidados">Limpar filtros</a></div>
    </form>
</section>
<section class="card">
    <div class="section-heading"><div><h2>Relatos coletivos por turma</h2><p><?=count($rows)?> relato(s) nos filtros selecionados. A impressão e o CSV incluem todos estes <?=count($rows)?> relatos.</p></div></div>
    <?php if(!$rows):?><div class="empty-state"><h3><?=$hasContributions?'Nenhum relato corresponde aos filtros':'Ainda não há contribuições'?></h3><p><?=$hasContributions?'Altere ou limpe os filtros para consultar outros relatos.':'Os textos aparecerão aqui conforme os professores preencherem o documento coletivo.'?></p></div><?php else:?>
    <div class="table"><table id="consolidated-table"><thead><tr><th>Período</th><th>Turno</th><th>Turma</th><th>Relato coletivo</th><th>Última atualização</th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td data-label="Período"><strong><?=e($row['periodo'])?></strong><small><?=e($row['ano_letivo'])?></small><?php if(isset($row['periodo_id'],$row['documento_turma_id'])):?><a href="/documentos/<?=e((int)$row['periodo_id'])?>#turma-<?=e((int)$row['documento_turma_id'])?>">Abrir documento de origem</a><?php endif;?></td><td data-label="Turno"><?=e($row['turno']==='VESPERTINO'?'Vespertino':($row['turno']==='MATUTINO'?'Matutino':'Todos os turnos'))?></td><td data-label="Turma"><?=e($row['turma'])?></td><td data-label="Relato" class="consolidated-narrative"><?=nl2br(e($row['relato']))?></td><td data-label="Última atualização"><strong><?=e($row['atualizado_por'])?></strong><small><?=e(date('d/m/Y H:i',strtotime($row['atualizado_em'])))?></small></td></tr><?php endforeach;?></tbody></table></div>
    <?php endif;?>
</section>
<?php $content=ob_get_clean();$pageClass='consolidated-page';require __DIR__.'/layout.php';
